package io.lumine.mythic.lib.module;
import java.util.*;import java.util.concurrent.ConcurrentHashMap;
public final class ModuleRegistry {private static final ModuleRegistry INSTANCE=new ModuleRegistry();private final Map<String,MMOPlugin> plugins=new ConcurrentHashMap<>();private volatile boolean registrationAllowed=true;private ModuleRegistry(){}public static ModuleRegistry getInstance(){return INSTANCE;}public MMOPlugin getPlugin(String key){return plugins.get(key==null?"":key.toLowerCase(Locale.ROOT));}public void registerPlugin(MMOPlugin plugin){if(!registrationAllowed)throw new IllegalStateException("Module registration is closed");plugins.put(plugin.getNamespacedKey().toLowerCase(Locale.ROOT),plugin);}public boolean isRegistrationAllowed(){return registrationAllowed;}public void loadModules(){registrationAllowed=false;}public Collection<MMOPlugin> plugins(){return List.copyOf(plugins.values());}}
